class ErrorBoundary extends React.Component {
  state = { hasError: false };

  static getDerivedStateFromError(error) {
    return { hasError: true };   // update state so the next render shows fallback UI
  }

  componentDidCatch(error, errorInfo) {
    console.error("Caught an error:", error, errorInfo);
    // could log to an error-reporting service here (Sentry, etc.)
  }

  render() {
    if (this.state.hasError) {
      return <h1>Something went wrong.</h1>;   // fallback UI instead of a crash
    }
    return this.props.children;
  }
}

function App() {
  return (
    <ErrorBoundary>
      <BuggyComponent />
    </ErrorBoundary>
  );
}

// 1. Errors in event handlers - NOT caught by an error boundary
function Button() {
  const handleClick = () => { throw new Error("oops"); };
  return <button onClick={handleClick}>Click</button>;
  // Fix: wrap the logic in a normal try/catch inside the handler itself
}

// 2. Errors in async code - NOT caught either
